import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])

    if n < 3:
        print(0)
        return

    a = []
    idx = 1
    for _ in range(n):
        a.append(int(input_data[idx]))
        idx += 1

    min_val = min(a)
    max_val = max(a)

    if min_val == max_val:
        print(0)
        return

    count = 0
    for x in a:
        if x > min_val and x < max_val:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
